              note: "四维动量是守恒的：一次碰撞里四个分量分别守恒，其中第 0 分量给出能量守恒，后三个给出三维动量守恒。由这个矢量能构造出一个不变量 $E^2 - (pc)^2 = (mc^2)^2$，它在所有惯性系里都一样，这就是「静止质量是不变量」的准确含义。"
