            "实验室系里的平均寿命：$\\Delta t = \\gamma\\Delta\\tau = 1.250\\,0\\times2.200\\ \\mu\\text{s} = 2.750\\ \\mu\\text{s}$，比固有时长 $25\\%$。",
            "这一寿命内 $\\mu$ 子能飞多远：$L = v\\Delta t = 0.600\\,0\\times2.997\\,924\\,58\\times10^{8}\\times2.750\\times10^{-6} = 495\\ \\text{m}$。换成 $\\mu$ 子自己的账：它只活了 $2.200\\ \\mu\\text{s}$，可它看到的大气层厚度被压缩成 $L/\\gamma = 495/1.250\\,0 = 396\\ \\text{m}$，$396\\ \\text{m}$ 除以 $0.6c$ 正好是 $2.200\\ \\mu\\text{s}$。**两套账必须给出同一个事实，这是相对论自洽性的最低要求。**",
