              note: "把 $\\nu = c/\\lambda$ 代进去可得波长变化。**这一条能在地面上直接检验**：1959 年庞德–雷布卡（Pound–Rebka）实验用 $22.5\\ \\text{m}$ 的高度差做出 $\\Delta\\nu/\\nu = 2.45\\times10^{-15}$ 的测量，与理论值 $gh/c^2 = 2.46\\times10^{-15}$ 相符。"
