            "**忘记史瓦西解是真空解，拿它去算太阳内部的引力。** 太阳中心处的引力势按另一种分布计算，内部解由托尔曼–奥本海默–沃尔科夫方程给出。判据：用到 $g_{00} = -(1-r_s/r)$ 时，确认所讨论的 $r$ 都在天体**外部**。",
            "**本讲省略了什么（必须说清楚）。** 本讲省略了：爱因斯坦场方程的建立与它的真空解求解过程（史瓦西解本身是直接给出的，不是推出来的）、里奇张量与爱因斯坦张量的完整计算、$\\Gamma$ 与 $R^\\mu_{\\ \\nu\\alpha\\beta}$ 的分量展开、类光测地线方程的高阶扰动与强偏折（绕圈）情形的处理、以及克尔解（转动天体）的内容。**这些省略不影响本讲结论的使用**：三条经典检验的公式都是弱场一阶结果，可以直接代入太阳系参数使用，误差在 $10^{-6}$ 量级。另外，仿真模型「schwarzschild」在光线偏折与轨道模式下都是**数值积分测地线方程**得到的轨迹，它的误差来源是积分步长与轨迹的截断——在 $b$ 接近光子球时误差明显变大；它**不含**自转（无克尔效应）、**不含**其他行星的摄动、也**不含**观测端的系统误差（如日冕折射、底片测量误差），所以它给出的是纯理论值，不能直接当作观测数据的替代品。"
