              note: "把它当「展开参数」用：所有相对论修正项都是 $\\epsilon$ 的幂次，一阶项给出可观测效应，二阶项在被测精度不足时可以丢掉。**先估 $\\epsilon$，再决定用哪一阶公式**，是本课后面每一讲的标准动作。"
