              note: "代入地球表面得 $6.96\\times10^{-10}$，即每天 $60\\ \\mu\\text{s}$、每年 $22\\ \\text{ms}$。**这个数字是从地面上一次重力红移实验（如 2010 年的光钟比对）到 GPS 修正的共同基础。**"
