              units: "$r_{\\text{ergo}}$: m；$a$ 无量纲（自转参数，$0 \\le a \\le 1$）；$J$: kg·m²/s（角动量）；$\\theta$: rad（余纬）",
              condition: "克尔时空（球对称但**自转**、不带电）。$a = 0$ 时 $r_+ = 2M$，正是史瓦西视界；$a \\to 1$ 时 $r_+ \\to M$。**必须提醒一处坐标约定的陷阱**：克尔度规的径向坐标与史瓦西度规的径向坐标定义不同（前者用 $M+\\sqrt{M^2-a^2}$ 这类约定），$a = 0$ 时克尔坐标下的 $r = 2M$ 与史瓦西的 $r_s = 2M$ **在数值上一致，但 $a \\ne 0$ 时两者不可直接比较**。跨解比较时请改用不变量（视界面积、曲率标量）。",
              note: "能层（ergosphere）是指「任何观察者都无法在那里保持静止、必然被拖动着转」的区域，它的外边界叫静界。**彭罗斯过程**正是在能层里把一个物体拆成两半、让其中一半带着负能量落进视界，从而提取黑洞的转动能——理论上可提取的最大能量占黑洞总质能的 $29\\%$（$a = 1$ 时）。"
