            "视界处的克雷奇曼标量：$K = \\dfrac{48G^2M^2}{c^4r_s^6}$。先算 $48G^2M^2/c^4 = 12r_s^2 = 12\\times(2.953\\times10^{4})^2 = 1.046\\times10^{10}\\ \\text{m}^2$；再除以 $r_s^6 = (2.953\\times10^{4})^6 = 6.631\\times10^{26}\\ \\text{m}^6$，得 $K = 1.58\\times10^{-17}\\ \\text{m}^{-4}$。**量纲检查**：$\\text{m}^2/\\text{m}^6 = \\text{m}^{-4}$，与曲率标量一致。它是有限值，**这就是「视界不是物理奇点」的定量结论**。",
            "静止悬停在 $r = 1.1\\,r_s$ 处的钟：$d\\tau/dt = \\sqrt{1-1/1.1} = \\sqrt{0.090\\,91} = 0.301\\,5$，红移 $z = 1/0.301\\,5-1 = 2.317$。**远处的观察者看到那里的钟慢到三成，光被红移 2.3 倍。**",
            "同一个黑洞在 $r = 1.001\\,r_s$ 处：$d\\tau/dt = \\sqrt{1-1/1.001} = \\sqrt{9.99\\times10^{-4}} = 0.0316$，$z = 30.6$。**从 $1.1\\,r_s$ 到 $1.001\\,r_s$，距离只近了 $0.099\\,r_s = 2.9\\ \\text{km}$，时间流逝率却掉了十倍。**",
            "潮汐加速度（人体在视界处）：$\\Delta a = \\dfrac{2GM\\Delta r}{r^3} = \\dfrac{2\\times1.327\\,124\\,4\\times10^{21}\\times1.8}{(2.953\\times10^{4})^3} = \\dfrac{4.778\\times10^{21}}{2.575\\times10^{13}} = 1.86\\times10^{8}\\ \\text{m/s}^2$。**约为地面重力的 1900 万倍**，远超人体组织的承受极限。",
            "换成超大质量黑洞：把 $M$ 提到 $10^{8}\\,M_\\odot$（$r_s = 2.953\\times10^{8}\\ \\text{km} = 1.97\\ \\text{AU}$），同样 $1.8\\ \\text{m}$ 的尺度：$\\Delta a = \\dfrac{2GM\\Delta r}{r^3}$ 中 $GM$ 放大 $10^{8}$ 倍、$r^3$ 放大 $10^{24}$ 倍，净效果缩小 $10^{16}$ 倍，得 $1.86\\times10^{-8}\\ \\text{m/s}^2$。**比地面重力还小九个数量级——所以在超大质量黑洞的视界处，潮汐力温和到人可以活着穿过去。** 这也解释了为什么恒星级黑洞的潮汐撕裂（tidal disruption）发生在视界**外面**很远的地方，而超大质量黑洞的恒星往往在视界附近才被撕开。",
            "霍金温度：$T_H = \\dfrac{\\hbar c^3}{8\\pi GMk_B} = \\dfrac{2.841\\times10^{-9}}{4.605\\times10^{1}} = 6.17\\times10^{-8}\\ \\text{K}$（对 $1\\,M_\\odot$）；对 $10\\,M_\\odot$ 再除以 10，得 $6.17\\times10^{-9}\\ \\text{K}$。**与宇宙微波背景的 $2.725\\ \\text{K}$ 相比低了八个数量级**，所以这个黑洞目前是净吸收的。把质量倒过来看：$T_H \\propto 1/M$，所以只有质量小到约 $10^{11}\\ \\text{kg}$（一座山丘的质量量级）的天体，$T_H$ 才会升到 $10^{12}\\ \\text{K}$ 这样可观的量级。",
            "贝肯斯坦–霍金熵：$S_{\\text{BH}} = \\dfrac{k_Bc^3A}{4G\\hbar}$，$A = 4\\pi r_s^2 = 4\\pi\\times8.720\\times10^{8} = 1.096\\times10^{10}\\ \\text{m}^2$。代入得 $S_{\\text{BH}} = \\dfrac{1.380\\,649\\times10^{-23}\\times(2.997\\,924\\,58\\times10^{8})^3\\times1.096\\times10^{10}}{4\\times6.674\\,30\\times10^{-11}\\times1.054\\,571\\,817\\times10^{-34}}$。分子：$c^3 = 2.694\\times10^{25}$，乘 $1.380\\,65\\times10^{-23}$ 得 $3.720\\times10^{2}$，再乘 $1.096\\times10^{10}$ 得 $4.077\\times10^{12}$；分母：$4\\times6.674\\times10^{-11}\\times1.055\\times10^{-34} = 2.816\\times10^{-44}$；相除得 $1.45\\times10^{56}\\ \\text{J/K}$。",
            "把熵换成无量纲形式更直观：$S_{\\text{BH}}/k_B = \\dfrac{c^3A}{4G\\hbar} = \\dfrac{A}{4\\ell_P^2}$，其中 $\\ell_P = \\sqrt{G\\hbar/c^3} = 1.616\\times10^{-35}\\ \\text{m}$ 是普朗克长度。于是 $S/k_B = 1.096\\times10^{10}/(4\\times2.612\\times10^{-70}) = 1.05\\times10^{79}$。**一个 $10\\,M_\\odot$ 黑洞的无量纲熵约 $10^{79}$，而太阳（约 $10^{57}$ 个粒子）的熵只有约 $10^{58}$——黑洞是宇宙里熵最大的物体。**"
