            "**把「黑洞无毛」理解成「黑洞什么信息都没有」。** 无毛定理说的是**外部**时空只由质量、角动量、电荷三个参数决定，不是「黑洞内部没有结构」；而且这三个参数之外的信息（比如掉进去的物体的成分）是否真的丢失，正是黑洞信息佯谬争论的核心，目前没有定论。判据：说「无毛」时必须限定在「外部稳态时空」。",
            "**把克尔黑洞的能层与视界混为一谈。** 能层是「静止观察者无法存在」的区域，它的外边界在视界**外面**；能层里物质必然被拖着转，但**仍然可以逃出去**，而视界以内不行。判据：能层是「不能静止」，视界是「不能出来」，两件事在概念上完全不同。",
            "**把克尔度规的 $r$ 坐标直接与史瓦西的 $r$ 比较。** 两套坐标的定义不同（视界位置在克尔坐标里是 $M+\\sqrt{M^2-a^2}$，在史瓦西里是 $2M$），直接套用会得到互相矛盾的数。判据：跨解比较时先统一约定，或者改用不变量（面积、曲率标量）作比较。",
            "**本讲省略了什么（必须说清楚）。** 本讲省略了：克尔度规的完整形式与其测地线方程的分离变量（卡特常数）、黑洞热力学的四条定律的推导、黑洞信息佯谬的详细讨论、彭罗斯过程的完整能量学计算、引力坍缩形成黑洞的动力学过程、以及任何形式的量子引力理论。**这些省略不影响本讲结论的使用**：视界的坐标奇点性质、时间膨胀、潮汐量级、$T_H$ 与 $S_{\\text{BH}}$ 的公式都是标准的可计算结论，可以直接使用；但**「黑洞内部到底发生了什么」与「信息是否守恒」这两个问题本讲没有回答，也不应该假装回答了**。另外，仿真模型「schwarzschild」在轨道模式下只积分**无自旋**的史瓦西轨道：它**不含**克尔效应（参考系拖曳、能层）、**不含**辐射反作用（引力波导致的轨道衰减）、也**不含**物质吸积。它的数值误差来自积分步长，在 $r$ 接近 $1.5\\,r_s$ 时会明显增大；读数里的 $z$ 与 $r_s$ 是解析计算，不受积分误差影响。"
