              units: "$r_\\pm$、$r_{\\text{ergo}}$: m（这里取 $G = c = 1$ 的几何单位，$M$ 的单位是 m）；$a = cJ/(GM^2)$ 无量纲，$0\\le a\\le1$",
              condition: "克尔时空（自转、不带电、真空）。$a = 0$ 时 $r_+ = 2M$（史瓦西视界）；$a \\to 1$ 时 $r_+ \\to M$ 而能层在赤道处扩展到 $2M$。$a > 1$ 时视界消失、露出裸奇点，宇宙监督假设认为这在物理上不可能实现。",
              note: "注意 $r_-$ 是内视界（柯西视界），它在 $r_+$ 以内，一般认为那里的经典演化会导致可预言性失效（质量膨胀现象）。**本课只讨论外视界 $r_+$。**"
