              note: "对 $30+30\\,M_\\odot$（$M_c = 30/2^{1/5} = 26.1165\\,M_\\odot$）、$f_0 = 35\\ \\text{Hz}$：$df/dt = 61.13\\ \\text{Hz/s}$、$t_c = 0.2147\\ \\text{s}$，与下面仿真实验读数区给出的 $61.1259\\ \\text{Hz/s}$ 和 $0.214\\,720\\,9\\ \\text{s}$ 一致。**这两个数可以用上面两条公式自己核一遍**：先算 $\\dfrac{GM_c}{c^3} = 26.1165\\times4.925\\,49\\times10^{-6} = 1.286\\,37\\times10^{-4}\\ \\text{s}$（$GM_\\odot/c^3 = 4.925\\,49\\times10^{-6}\\ \\text{s}$ 是值得背下来的一个常数，$M_c$ 用太阳质量作单位时直接乘它），于是 $\\left(\\dfrac{GM_c}{c^3}\\right)^{5/3} = 3.278\\,0\\times10^{-7}$、$f_0^{11/3} = 35^{11/3} = 4.587\\,6\\times10^{5}$，代入第一式得 $df/dt = 406.5\\times3.278\\,0\\times10^{-7}\\times4.587\\,6\\times10^{5} = 406.5\\times0.150\\,38 = 61.13\\ \\text{Hz/s}$；同一条 $GM_c/c^3$ 代进第二式得 $t_c = 1.953\\,1\\times10^{-2}\\times3.050\\,6\\times10^{6}\\times3.603\\,7\\times10^{-6} = 0.2147\\ \\text{s}$。**两条公式还可以互相校验**：解析解给出 $t_c = \\dfrac{3}{8}\\dfrac{f_0}{df/dt}$，代入得 $0.375\\times35/61.13 = 0.2147\\ \\text{s}$，与上式一致。**「0.21 秒」正是 LIGO 在 35 Hz 以上能看到的信号长度**——这也是为什么这段信号被称为「啁啾」：0.2 秒里频率从 35 Hz 升到 150 Hz 以上。"
