              units: "$h$ 无量纲（长度相对变化）；$d_L$: m（光度距离）；$GM_c/c^2$: m（啁啾质量的引力半径）；$f$: Hz",
              condition: "面向探测器的**最优取向**（轨道平面垂直于视线），且只保留振幅的最低阶项。**真实事件的应变还要乘上取向因子**（$0$ 到 $1$ 之间，平均约 $0.4$），所以同一次并合在不同方向上的 $h$ 可以差好几倍。",
              note: "对 GW150914（$m_1 = 36\\,M_\\odot$、$m_2 = 29\\,M_\\odot$，$M_c = 28.1\\,M_\\odot$，$d_L = 410\\ \\text{Mpc}$）、$f = 150\\ \\text{Hz}$：$h = 1.0\\times10^{-21}$。**这个数字是全课最应该记住的一个量级：$10^{-21}$。**"
