              units: "$P$: W（= J/s）；$Q$: kg·m²（质量四极矩）；$\\dddot{Q}$: kg·m²/s³；$G/c^5 = 2.76\\times10^{-53}\\ \\text{s/(kg}\\cdot\\text{m}^2)$",
              condition: "弱场、慢速（$v \\ll c$）的四极辐射近似。强场并合的末段与铃宕阶段必须用数值相对论求解，四极公式只给出量级估计。",
              note: "把 $\\dddot{Q} \\sim Mr^2\\omega^3$ 代入：$P \\propto M^2r^4\\omega^6$。**这个 $\\omega^6$ 是引力波「越到后面越猛」的根源**——两个黑洞每靠近一点，频率上升、振幅猛增，直到并合瞬间的峰值功率约 $3.6\\times10^{49}\\ \\text{W}$。**这个数字约为可观测宇宙全部恒星总光度（约 $10^{49}\\ \\text{W}$）的量级**，也就是说：在那 0.2 秒里，这一个双星系统的引力波功率与整个宇宙的星光相当。"
