            "**本讲省略了什么（必须说清楚）。** 本讲省略了：引力波的完整线性化推导与 TT 规范下的偏振分解细节、后牛顿展开的高阶项与数值相对论、并合后的铃宕（准正规模）频谱计算、干涉仪的全部噪声源与灵敏度曲线推导、标准汽笛的完整统计处理（倾角、弱透镜、星系巡天带来的系统误差）、以及宇宙学部分的 Friedmann 方程求解与距离积分的数值方法。**这些省略不影响本讲结论的使用**：啁啾质量、$df/dt$、$t_c$ 与 $h$ 这四条公式都是牛顿（四极）近似下的结果，用来理解与估算 LIGO 量级的事件足够；$H_0$ 与 $\\rho_c$ 的关系是精确的（对均匀各向同性宇宙）。另外，仿真模型「gravity-wave」用的是**四极近似下的解析频率演化加数值积分**，它**不含**后牛顿高阶项、**不含**黑洞自旋（自旋会改变并合前的圈数与波形）、**不含**偏心轨道、也**不含**探测器响应与噪声——所以它给出的是「理论波形」，不是「LIGO 记录到的数据」。模型「cosmology」同样是**均匀各向同性**的 Friedmann 模型，它**不含**结构形成、不含辐射组分（$\\Omega_r$ 取 $0$）、也不含原初扰动，所以它算不出微波背景的声学峰。"
